  this.adT = "W\u0119ze\u0142 nie poda\u0142 dowodu dla tego konta.";
  this.acL = "Podsumowanie w\u0119z\u0142a nie jest podpisane jego kluczem.";
  this.aem = "Tw\u00f3j \u0142a\u0144cuch nie wchodzi w podpisane podsumowanie w\u0119z\u0142a.";
  this.ack = "To urz\u0105dzenie policzy\u0142o wszystko samo; w\u0119ze\u0142 zosta\u0142 poproszony tylko o zapisy.";
  this.adr = "Uczestnicy";
  this.afX = "Suma sald";
  this.afY = "Suma wszystkich sald zawsze wynosi zero: jednostka powstaje, gdy uczestnik kupuje, i znika, gdy sprzedaje.";
  this.adq = "Uczestnik";
  this.acg = "Linia kredytowa";
  this.abE = "Pu\u0142ap";
  this.adS = "nie ma jeszcze uczestnik\u00f3w";
