  this.anr = "\u0437\u0430 \u0434\u043e\u043c\u043e\u0432\u043b\u0435\u043d\u0456\u0441\u0442\u044e";
  this.aoW = "\u041e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438, %";
  this.aoX = "\u044f\u043a\u0443 \u0447\u0430\u0441\u0442\u043a\u0443 \u0446\u0456\u043d\u0438 \u0432\u0438 \u0431\u0435\u0440\u0435\u0442\u0435 \u0430\u0431\u043e \u043f\u043b\u0430\u0442\u0438\u0442\u0435 \u043e\u0434\u0438\u043d\u0438\u0446\u044f\u043c\u0438: 100 \u2014 \u0443\u0441\u044e, 50 \u2014 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0443";
