  this.apy = "\u0426\u0435\u0439 \u043f\u043b\u0430\u0442\u0456\u0436 \u0437\u0430\u043f\u0440\u043e\u043f\u043e\u043d\u0443\u0432\u0430\u043b\u0438 \u0432\u0438: \u043f\u0456\u0434\u0442\u0432\u0435\u0440\u0434\u0438\u0442\u0438 \u0439\u043e\u0433\u043e \u043c\u0430\u0454 \u0456\u043d\u0448\u0438\u0439 \u0442\u0440\u0438\u043c\u0430\u0447.";
