  this.aqZ = "\u041f\u043e\u043b\u0456\u0442\u0438\u043a\u0430";
  this.ar5 = "\u0412\u043b\u0430\u0441\u043d\u0430 \u043f\u043e\u043b\u0456\u0442\u0438\u043a\u0430 \u0433\u0440\u043e\u043c\u0430\u0434\u0438: \u0434\u0456\u0454 \u0437 \u043c\u043e\u043c\u0435\u043d\u0442\u0443 \u0437\u0431\u0435\u0440\u0435\u0436\u0435\u043d\u043d\u044f \u0434\u043b\u044f \u043a\u043e\u0436\u043d\u043e\u0433\u043e \u0440\u0430\u0445\u0443\u043d\u043a\u0443. \u041b\u0456\u043d\u0456\u0457, \u0432\u0438\u0434\u0430\u043d\u0456 \u0440\u0430\u043d\u0456\u0448\u0435, \u043b\u0438\u0448\u0430\u044e\u0442\u044c\u0441\u044f \u044f\u043a \u0454. \u0425\u0430\u0431, \u043d\u0430 \u044f\u043a\u043e\u043c\u0443 \u0441\u0442\u043e\u0457\u0442\u044c \u0433\u0440\u043e\u043c\u0430\u0434\u0430, \u043c\u043e\u0436\u0435 \u0434\u043e\u0437\u0432\u043e\u043b\u044f\u0442\u0438 \u043c\u0435\u043d\u0448\u0435, \u043d\u0456\u0436 \u043f\u0440\u043e\u043f\u043e\u043d\u0443\u044e\u0442\u044c \u0434\u0435\u0456\u043d\u0434\u0435.";
  this.ar1 = "\u0412\u0441\u0442\u0443\u043f \u0456 \u0431\u0456\u0437\u043d\u0435\u0441\u0438";
