  this.ar3 = "\u041a\u0440\u0435\u0434\u0438\u0442 \u043f\u0440\u0438\u0432\u0430\u0442\u043d\u0456\u0439 \u043e\u0441\u043e\u0431\u0456, \u043d\u0430\u0432\u0456\u0442\u044c \u0431\u0435\u0437\u0432\u0456\u0434\u0441\u043e\u0442\u043a\u043e\u0432\u0438\u0439, \u043c\u043e\u0436\u0435 \u043f\u0456\u0434\u043f\u0430\u0434\u0430\u0442\u0438 \u043f\u0456\u0434 \u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u0441\u043f\u043e\u0436\u0438\u0432\u0447\u043e\u0433\u043e \u043a\u0440\u0435\u0434\u0438\u0442\u0443. \u0414\u0435 \u043b\u044e\u0434\u0438 \u0441\u043f\u0435\u0440\u0448\u0443 \u0437\u0430\u0440\u043e\u0431\u043b\u044f\u044e\u0442\u044c, \u0430 \u043f\u043e\u0442\u0456\u043c \u0432\u0438\u0442\u0440\u0430\u0447\u0430\u044e\u0442\u044c, \u043a\u0440\u0435\u0434\u0438\u0442 \u043d\u0435 \u0432\u0438\u0434\u0430\u0454\u0442\u044c\u0441\u044f \u0456 \u043f\u0438\u0442\u0430\u043d\u043d\u044f \u043d\u0435 \u0432\u0438\u043d\u0438\u043a\u0430\u0454.";
